create table if not exists public.ils_professional_assignment_revocation_audit (id uuid primary key default gen_random_uuid(),assignment_link_id uuid,work_stream text,work_item_id uuid,professional_user_id uuid,decision text not null,reason_code text not null,checks jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_revocation_audit enable row level security; revoke all on public.ils_professional_assignment_revocation_audit from anon,authenticated; create or replace function public.ils_professional_assignment_is_current(p_work_item_id uuid,p_work_stream text,p_professional_user_id uuid) returns boolean language sql security definer stable set search_path=public as $$ select case when auth.uid() is null or auth.uid()<>p_professional_user_id or p_work_item_id is null or p_work_stream not in ('PROFESSIONAL','B2B') then false when not exists(select 1 from public.ils_associate_trust_profiles t where t.user_id=p_professional_user_id and t.profile_status='ACTIVE' and t.identity_verified=true and t.qualification_verified=true and t.professional_registration_verified=true and t.capability_verified=true) then false when p_work_stream='PROFESSIONAL' then exists(select 1 from public.ils_professional_work_items w join public.ils_professional_work_assignment_links l on l.work_item_id=w.id and l.work_stream='PROFESSIONAL' and l.professional_user_id=p_professional_user_id and l.link_status='APPROVED' join public.ils_unified_assignment_decisions u on u.id=l.assignment_decision_id and u.associate_user_id=p_professional_user_id and u.decision='ALLOW' and u.requires_supervision=false and u.requires_professional_review=false where w.id=p_work_item_id and w.professional_user_id=p_professional_user_id) when p_work_stream='B2B' then exists(select 1 from public.ils_b2b_work_items w join public.ils_professional_work_assignment_links l on l.work_item_id=w.id and l.work_stream='B2B' and l.professional_user_id=p_professional_user_id and l.link_status='APPROVED' join public.ils_unified_assignment_decisions u on u.id=l.assignment_decision_id and u.associate_user_id=p_professional_user_id and u.decision='ALLOW' and u.requires_supervision=false and u.requires_professional_review=false where w.id=p_work_item_id and w.professional_user_id=p_professional_user_id) else false end $$; revoke all on function public.ils_professional_assignment_is_current(uuid,text,uuid) from public,anon,authenticated; grant execute on function public.ils_professional_assignment_is_current(uuid,text,uuid) to authenticated; drop policy if exists professional_own_assigned_work_select on public.ils_professional_work_items; drop policy if exists b2b_own_assigned_work_select on public.ils_b2b_work_items; create policy professional_own_current_assigned_work_select on public.ils_professional_work_items for select to authenticated using (public.ils_professional_assignment_is_current(id,'PROFESSIONAL',professional_user_id)); create policy b2b_own_current_assigned_work_select on public.ils_b2b_work_items for select to authenticated using (public.ils_professional_assignment_is_current(id,'B2B',professional_user_id)); drop policy if exists professional_own_assigned_events_select on public.ils_professional_work_events; drop policy if exists b2b_own_assigned_events_select on public.ils_b2b_work_events; create policy professional_own_current_assigned_events_select on public.ils_professional_work_events for select to authenticated using (exists(select 1 from public.ils_professional_work_items w where w.id=ils_professional_work_events.work_item_id and public.ils_professional_assignment_is_current(w.id,'PROFESSIONAL',w.professional_user_id))); create policy b2b_own_current_assigned_events_select on public.ils_b2b_work_events for select to authenticated using (exists(select 1 from public.ils_b2b_work_items w where w.id=ils_b2b_work_events.work_item_id and public.ils_professional_assignment_is_current(w.id,'B2B',w.professional_user_id))); create index if not exists idx_ils_assignment_revocation_audit_user on public.ils_professional_assignment_revocation_audit(professional_user_id,created_at desc);